const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const greatLakes = ee.Geometry.Polygon([
    [-92.0, 46.0], [-92.0, 41.0], [-76.0, 41.0], [-76.0, 46.0], [-92.0, 46.0]
  ]);

  const date1 = '2021-02-20';
  const date2 = '2021-03-03';

  // 2. Data Acquisition - MODIS Terra Snow Cover
  const modisCol1 = ee.ImageCollection('MODIS/061/MOD10A1')
    .filterDate(date1, ee.Date(date1).advance(1, 'day'))
    .filterBounds(greatLakes);

  const modisCol2 = ee.ImageCollection('MODIS/061/MOD10A1')
    .filterDate(date2, ee.Date(date2).advance(1, 'day'))
    .filterBounds(greatLakes);

  // Check collection sizes
  const size1 = modisCol1.size().getInfo();
  const size2 = modisCol2.size().getInfo();

  console.log(`Feb 20 Images: ${size1}, Mar 03 Images: ${size2}`);

  if (size1 === 0 || size2 === 0) {
    console.log("<answer>C1</answer>");
    return;
  }

  // Get first image from each collection
  const img1 = modisCol1.first();
  const img2 = modisCol2.first();

  // Use NDSI_Snow_Cover band (0-100% snow/ice cover)
  const band = 'NDSI_Snow_Cover';

  // 3. Calculate mean ice coverage for each date
  const mean1 = img1.select(band).reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: greatLakes,
    scale: 1000,
    maxPixels: 1e9
  }).get(band);

  const mean2 = img2.select(band).reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: greatLakes,
    scale: 1000,
    maxPixels: 1e9
  }).get(band);

  // Get pixel counts to check for valid data
  const count1 = img1.select(band).reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: greatLakes,
    scale: 1000,
    maxPixels: 1e9
  }).get(band);

  const count2 = img2.select(band).reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: greatLakes,
    scale: 1000,
    maxPixels: 1e9
  }).get(band);

  // Get all values
  const [val1, val2, cnt1, cnt2] = await Promise.all([
    mean1.getInfo(), mean2.getInfo(), count1.getInfo(), count2.getInfo()
  ]);

  console.log(`Feb 20 Ice: ${val1 !== null ? val1.toFixed(2) : 'null'}%, Pixels: ${cnt1}`);
  console.log(`Mar 03 Ice: ${val2 !== null ? val2.toFixed(2) : 'null'}%, Pixels: ${cnt2}`);

  // 4. Validation & Final Answer
  if (cnt1 === 0 || cnt2 === 0) {
    console.log("<answer>C2</answer>");
    return;
  }

  if (val1 === null || val2 === null || isNaN(val1) || isNaN(val2)) {
    console.log("<answer>C3</answer>");
    return;
  }

  // Check if ice coverage decreased
  if (val2 < val1) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
